def get_network_share_mount_script() -> str:
    """
    Generate mount script for all active auto-mount network shares.

    Returns:
        A bash script that installs necessary packages and mounts all configured shares
    """
    from app.models import NetworkShare
    from app import db

    # Query all active auto-mount shares
    shares = NetworkShare.query.filter_by(is_active=True, auto_mount=True).all()

    if not shares:
        return ''

    # Start building the script
    script_parts = ['''
echo "=== Setting up network shares ==="
''']

    # Track which packages we need
    needs_nfs = any(s.share_type == 'nfs' for s in shares)
    needs_cifs = any(s.share_type == 'samba' for s in shares)

    # Install necessary packages
    packages = []
    if needs_nfs:
        packages.append('nfs-common')
    if needs_cifs:
        packages.append('cifs-utils')

    if packages:
        script_parts.append(f'''
# Install required packages
apt-get update
apt-get install -y {' '.join(packages)}
''')

    # Create mount points and mount each share
    for share in shares:
        mount_point = share.mount_point
        script_parts.append(f'''
# Setting up share: {share.name}
mkdir -p {mount_point}
''')

        if share.share_type == 'nfs':
            # NFS mount
            mount_opts = share.mount_options or 'defaults'
            nfs_path = f"{share.server}:{share.share_path}"
            script_parts.append(f'''
echo "Mounting NFS share {share.name} at {mount_point}..."
mount -t nfs -o {mount_opts} {nfs_path} {mount_point}
if [ $? -eq 0 ]; then
    echo "{nfs_path} {mount_point} nfs {mount_opts} 0 0" >> /etc/fstab
    echo "NFS share {share.name} mounted successfully"
else
    echo "Warning: Failed to mount NFS share {share.name}"
fi
''')

        elif share.share_type == 'samba':
            # Samba/CIFS mount
            mount_opts = share.mount_options or 'defaults'

            # Handle credentials if provided
            if share.windows_credential:
                cred = share.windows_credential
                username = cred.username
                password = cred.password.replace("'", "'\\''")  # Escape single quotes
                domain = cred.domain or ''

                # Create credentials file
                creds_file = f"/root/.smbcredentials_{share.id}"
                script_parts.append(f'''
# Create credentials file for {share.name}
cat > {creds_file} <<'CREDEOF'
username={username}
password={password}
''')
                if domain:
                    script_parts.append(f'''domain={domain}
''')
                script_parts.append(f'''CREDEOF
chmod 600 {creds_file}
''')

                # Mount with credentials
                mount_opts_with_creds = f"{mount_opts},credentials={creds_file}"
                script_parts.append(f'''
echo "Mounting Samba share {share.name} at {mount_point}..."
mount -t cifs -o {mount_opts_with_creds} {share.share_path} {mount_point}
if [ $? -eq 0 ]; then
    echo "{share.share_path} {mount_point} cifs {mount_opts_with_creds} 0 0" >> /etc/fstab
    echo "Samba share {share.name} mounted successfully"
else
    echo "Warning: Failed to mount Samba share {share.name}"
fi
''')
            else:
                # Mount without credentials (guest access)
                mount_opts_guest = f"{mount_opts},guest"
                script_parts.append(f'''
echo "Mounting Samba share {share.name} (guest) at {mount_point}..."
mount -t cifs -o {mount_opts_guest} {share.share_path} {mount_point}
if [ $? -eq 0 ]; then
    echo "{share.share_path} {mount_point} cifs {mount_opts_guest} 0 0" >> /etc/fstab
    echo "Samba share {share.name} mounted successfully"
else
    echo "Warning: Failed to mount Samba share {share.name}"
fi
''')

    script_parts.append('''
echo "=== Network shares setup complete ==="
''')

    return ''.join(script_parts)


def get_install_script(container_key: str, include_ssh_setup: bool = True, ssh_key: str = '') -> str:
    """
    Get the installation script for a container.

    Args:
        container_key: The container definition key
        include_ssh_setup: Whether to prepend SSH setup script (default: True)
        ssh_key: Optional SSH public key to add to authorized_keys

    Returns:
        The installation script as a string
    """
    script = INSTALL_SCRIPTS.get(container_key, INSTALL_SCRIPTS.get("default"))

    # Build SSH key injection script if key provided
    ssh_key_script = ''
    if ssh_key and ssh_key.strip():
        # Escape any special characters in the key for bash
        escaped_key = ssh_key.strip().replace("'", "'\\''")
        ssh_key_script = f'''
# Add SSH public key to authorized_keys
echo "Adding SSH public key to authorized_keys..."
mkdir -p /root/.ssh
chmod 700 /root/.ssh
echo '{escaped_key}' >> /root/.ssh/authorized_keys
chmod 600 /root/.ssh/authorized_keys
chown -R root:root /root/.ssh
echo "SSH key added successfully"
'''

    # Get network share mount script
    network_share_script = get_network_share_mount_script()

    if script and include_ssh_setup:
        # Prepend SSH setup to the script, after the shebang if present
        if script.startswith('#!/bin/bash'):
            script = '#!/bin/bash\nset -e\n' + SSH_SETUP_SCRIPT + '\n' + ssh_key_script + '\n' + network_share_script + '\n' + script.replace('#!/bin/bash', '').lstrip()
        else:
            script = '#!/bin/bash\nset -e\n' + SSH_SETUP_SCRIPT + '\n' + ssh_key_script + '\n' + network_share_script + '\n' + script
    elif ssh_key_script or network_share_script:
        # No SSH setup but we have a key to add or network shares to mount
        if script and script.startswith('#!/bin/bash'):
            script = '#!/bin/bash\nset -e\n' + ssh_key_script + '\n' + network_share_script + '\n' + script.replace('#!/bin/bash', '').lstrip()
        elif script:
            script = '#!/bin/bash\nset -e\n' + ssh_key_script + '\n' + network_share_script + '\n' + script
        else:
            script = '#!/bin/bash\nset -e\n' + ssh_key_script + '\n' + network_share_script

    return script


def get_all_install_scripts() -> dict:
    """Get all installation scripts."""
    return INSTALL_SCRIPTS


